        captureHotkey:            store.get('captureHotkey'),
        pasteHotkey1:             store.get('pasteHotkey1'),
        pasteHotkey2:             store.get('pasteHotkey2'),
        pasteHotkey3:             store.get('pasteHotkey3'),
        examDotPhrase:            store.get('examDotPhrase'),
