// ── Claude API ──────────────────────────────────────────────────────────────

const BUILT_IN_API_KEY = ''; // Removed — set your key in Settings → Claude API

const BASE_SYSTEM_PROMPT = `You are a medical note reformatter. Transform the input according to these rules:

NAME REMOVAL:
- Delete all instances of "Dr. Haring"

MEDICATIONS:
- Continued/unchanged medications → combine into single bullet: "- Continue: [med1], [med2], [med3]"
- New medications → "- Start: [medication]"
- Stopped medications → "- Stop: [medication]"
- Changed medications → "- Change: [medication to new dosage/frequency]"
- Only include Start/Stop/Change bullets when actual changes exist

RECOMMENDATIONS:
- Preserve "Consider" language verbatim (don't convert to directives)

PROCEDURES:
- Each procedure gets its own bullet point
- Note if procedure was "performed today" vs "scheduled"

ABBREVIATIONS (expand all):
- BID → twice daily
- TID → three times daily
- QID → four times daily
- QD → once daily
- PRN → as needed
- PO → by mouth
- IM → intramuscular
- IV → intravenous
- ESI → epidural steroid injection
- TFESI → transforaminal epidural steroid injection
- ILESI → interlaminar epidural steroid injection
- CESI → caudal epidural steroid injection
- RFA → radiofrequency ablation
- MBB → medial branch block
- SI → sacroiliac
- SIJ → sacroiliac joint
- CRPS → complex regional pain syndrome
- PT → physical therapy
- OT → occupational therapy
- MRI → magnetic resonance imaging
- CT → computed tomography
- EMG → electromyography
- NCS → nerve conduction study
- NSAID → nonsteroidal anti-inflammatory drug
- HA → headache
- LBP → low back pain
- ROM → range of motion
- WNL → within normal limits
- F/U → follow up
- RTC → return to clinic

OUTPUT FORMAT:
- Use dash-space bullets ( - )
- No blank lines between bullets
- Single line per bullet (no wrapping)
- No nested sub-bullets
- Output ONLY the formatted bullets, no explanations
- At the END, on a new line, output one of these codes based on content:
  [CODE:NO_CHANGES] - if no medication changes and no procedures
  [CODE:MED_CHANGES] - if medication changes only (Start/Stop/Change present)
  [CODE:MED_AND_SCHEDULED] - if medication changes AND a scheduled procedure
  [CODE:PROCEDURE_TODAY] - if a procedure was performed today`;

const ACTION_ITEM_PROMPT = `You are a medical note assistant. Given an Assessment and Plan section from a clinical note, extract only the concrete action items and output them as a concise bullet list.

INCLUDE these categories (when present):
- Medication changes: start, stop, or change (keep drug names and doses as written)
- Procedures ordered or scheduled
- Referrals
- Labs or imaging ordered
- Follow-up instructions (e.g. return to clinic timeframes)

DO NOT include:
- Diagnoses or problem descriptions
- Findings or exam results
- Rationale or explanations
- Anything that is not a discrete action

FORMAT:
- Use dash-space bullets (- )
- One action per bullet
- Keep abbreviations as-is (do not expand)
- No blank lines between bullets
- No preamble, headers, or explanation — output ONLY the bullet list
- If no action items are found, output nothing — return an empty string`;

async function extractActionItems(apText) {
    const apiKey = (store.get('claudeApiKey') || '').trim() || BUILT_IN_API_KEY;

    if (!apiKey || apiKey === '') {
        console.error('extractActionItems: No API key available');
        if (mainWindow) mainWindow.webContents.send('bullets-ready', {
            apPreview: null,
            error: 'No API key — go to Settings → Claude API to enter your key'
        });
        return null;
    }

    try {
        const response = await net.fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': apiKey,
                'anthropic-version': '2023-06-01'
            },
            body: JSON.stringify({
                model: CLAUDE_MODEL,
                max_tokens: 512,
                system: ACTION_ITEM_PROMPT,
                messages: [{ role: 'user', content: apText }]
            })
        });
        const data = await response.json();
        if (!response.ok) {
            console.error('extractActionItems API error:', data.error?.message || response.status);
            throw new Error(data.error?.message || `HTTP ${response.status}`);
        }
        return (data.content[0].text || '').trim();
    } catch (e) {
        console.error('Action item extraction failed:', e.message);
        return null;
    }
}

const DEFAULT_ATTESTATION_TEMPLATE = `For this patient encounter, I personally saw this patient and formulated the plan together with the APP at the time of this visit. I agree with the [DYNAMIC_PLAN_TEXT]. I reviewed the APP's documentation, medical decision making and treatment plan, and agree with the documentation above. By my electronic signature I authenticate all APP orders and attest that all pages have been reviewed and completed.

Physical exam: Gen: No acute distress
HEENT: EOMI, NC/AT
CV: Extremities warm and perfused.
Pulm: No increased work of breathing.
Neuro: Moves extremities spontaneously. Alert and oriented.
Psych: Answered all questions appropriately.

Assessment: As above

Plan:

`;

async function callClaudeAPI(text, customInstructions) {
    const apiKey = store.get('claudeApiKey') || BUILT_IN_API_KEY;
    if (!apiKey || !apiKey.trim()) {
        return { success: false, error: 'No API key set. Go to Settings → Claude API to enter your key.' };
    }

    let systemPrompt = BASE_SYSTEM_PROMPT;
    if (customInstructions && customInstructions.trim()) {
        systemPrompt += '\n\nADDITIONAL INSTRUCTIONS:\n' + customInstructions;
    }

    try {
        const response = await net.fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': apiKey,
                'anthropic-version': '2023-06-01'
            },
            body: JSON.stringify({
                model: CLAUDE_MODEL,
                max_tokens: 4096,
                system: systemPrompt,
                messages: [{ role: 'user', content: text }]
            })
        });

        const data = await response.json();

        if (!response.ok) {
            throw new Error(data.error?.message || 'API error');
        }

        return { success: true, text: data.content[0].text };
    } catch (error) {
        return { success: false, error: error.message };
    }
}

// ── App lifecycle ───────────────────────────────────────────────────────────

function migrateHotkeys() {
    const altKeys = ['Alt+C', 'Alt+1', 'Alt+2', 'Alt+3', 'Alt+X', 'Alt+Z', 'Alt+H', 'Alt+4', 'Alt+5', 'Alt+6'];
    const migrations = { captureHotkey: 'F8', pasteHotkey1: 'F9', pasteHotkey2: 'F10', pasteHotkey3: 'F11' };
    for (const [key, defaultVal] of Object.entries(migrations)) {
        const current = store.get(key);
        if (!current || altKeys.includes(current)) { store.set(key, defaultVal); }
    }
}
migrateHotkeys();

app.whenReady().then(() => {
    try {
        createMainWindow();
        registerHotkeys();
        if (process.platform === 'win32') {
            writeAhkConfig(store.get('examDotPhrase') || '');
            launchAHK();
            watchSlotsFile();
        }
    } catch (err) {
        const { dialog } = require('electron');
        dialog.showErrorBox(
            'MedicalNoteAttestor — Startup Error',
            'Failed to start:\n\n' + err.message + '\n\n' + (err.stack || '')
        );
        app.quit();
    }
    app.on('activate', () => {
        if (BrowserWindow.getAllWindows().length === 0) {
            createMainWindow();
        }
    });
}).catch(err => {
    try {
        require('electron').dialog.showErrorBox(
            'MedicalNoteAttestor — Fatal Error',
            'Fatal startup error:\n\n' + err.message + '\n\n' + (err.stack || '')
        );
    } catch(e) {}
    app.quit();
});

app.on('window-all-closed', () => { globalShortcut.unregisterAll(); killAHK(); app.quit(); });

app.on('will-quit', () => { globalShortcut.unregisterAll(); killAHK(); });
